{
  "results": [
    {
      "server": "agend",
      "tools": [
        {
          "tool_name": "agend__reply",
          "description": "Reply on the channel. Routing is handled automatically — do not pass chat_id or thread_id. Add `buttons` to offer choices people can click.",
          "score": 1.0,
          "input_schema": {
            "type": "object",
            "properties": {
              "text": {
                "description": "The message. Required unless you send stickers; with stickers it may be omitted.",
                "type": "string"
              },
              "reply_to": {
                "description": "Message ID to thread under. Use message_id from the inbound block.",
                "type": "string"
              },
              "files": {
                "description": "Absolute file paths to attach (at most 20). Files under the AgEnD state dir (~/.agend, incl. workspaces/) are refused — copy an artifact to /tmp first and attach that. For HTML the web chat should preview, attach a .html file (it previews at once up to 8 MB, after the person confirms up to 50 MB) rather than pasting the page into text: a long ```html block is split on Discord/Telegram; keep ```html blocks for short snippets. The preview has no network: inline libraries, unless the fleet allows CDN ones (web.preview_cdn: cdnjs /ajax/libs/, jsDelivr /npm/).",
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "format": {
                "description": "Rendering mode. Default: 'text'.",
                "type": "string",
                "enum": [
                  "text",
                  "markdown"
                ]
              },
              "stickers": {
                "description": "Up to 3 sticker ids from list_stickers, sent with the text (Discord: the same message; Telegram: after it). Stickers are never written in the text.",
                "maxItems": 3,
                "type": "array",
                "items": {
                  "type": "string",
                  "minLength": 1
                }
              },
              "buttons": {
                "description": "Up to 10 buttons under the text (needs text; not with stickers). The first click by someone who may talk to you there answers for everyone and comes back to you as a message: `[button] <label>` (and `(value: …)` when it differs). Unanswered buttons expire after 24 h. With `poll`, they are a poll's options instead.",
                "minItems": 1,
                "maxItems": 10,
                "type": "array",
                "items": {
                  "type": "object",
                  "properties": {
                    "label": {
                      "type": "string",
                      "minLength": 1,
                      "maxLength": 80,
                      "description": "What the button says: one line of plain text, at most 80 characters."
                    },
                    "value": {
                      "description": "What you receive when it is clicked, if not the label (at most 200 characters; never shown on the platform).",
                      "type": "string",
                      "maxLength": 200
                    }
                  },
                  "required": [
                    "label"
                  ],
                  "additionalProperties": false
                }
              },
              "poll": {
                "description": "Make the buttons (2–10) a timed poll: everyone who may talk to you there votes once, may change their vote, and is told their own choice privately. At the deadline you get one message from AgEnD in the poll's chat, `[poll results]`: each option's count and voters, each with an id and the ms from the poll opening (just before it is posted) to their last change; answer it in the chat. AgEnD only counts votes: post the right answer and any scores yourself. The reply's result has `poll_id`.",
                "type": "object",
                "properties": {
                  "seconds": {
                    "type": "integer",
                    "minimum": 10,
                    "maximum": 86400,
                    "description": "When the poll closes: 10 s to 24 h after it is posted."
                  },
                  "multi": {
                    "description": "Each voter may pick several options (a click toggles one). Default: one.",
                    "type": "boolean"
                  },
                  "reveal": {
                    "description": "\"close\" (default): while open only \"N answered\" and the time left show, the counts at close. \"live\": the counts show as votes come.",
                    "type": "string",
                    "enum": [
                      "close",
                      "live"
                    ]
                  },
                  "show_voters": {
                    "description": "At close, also post who picked what in the chat. Default: counts only. You get the voters either way.",
                    "type": "boolean"
                  }
                },
                "required": [
                  "seconds"
                ],
                "additionalProperties": false
              }
            },
            "additionalProperties": false
          }
        }
      ]
    }
  ],
  "total_hidden_tools": 81,
  "status": "ready",
  "note": null
}
